import { chainClient, compareLogs } from './client.js';
import { eventFacts } from './facts.js';
import { lootboxSession, inLootboxSession } from './recycling.js';
import { prepareWalletReceipt } from '../app/wallet-receipt.js';

// Pending work has no age limit. Reuse the same deployment-bounded, cached
// player event stream as pendingBets instead of restarting a recent-log scan.
// Physical (index, betId) pairs repeat, so a placement owns its RNG session.
export async function readDegeneretteReplay({
  player, index, betId, packedData = null, rngWord = null, placementHash = null,
  client = chainClient(),
}) {
  const s = await client.snapshot();
  const anchor = placementHash ? await client.receipt(placementHash) : null;
  if (placementHash && anchor?.blockNumber == null) return null;
  const rows = await eventFacts(s, ['DegeneretteBetPlaced', 'DegeneretteResolved'], {
    contract: 'GAME', player, fromBlock: anchor?.blockNumber,
  });
  const matches = row => String(row.args.index) === String(index)
    && String(row.args.betId) === String(betId);
  const placements = rows.filter(row => row.name === 'DegeneretteBetPlaced' && matches(row)
    && (packedData == null || BigInt(row.args.packed) === BigInt(packedData))
    && (!placementHash || row.transactionHash.toLowerCase() === placementHash.toLowerCase()));
  const candidates = [];
  for (const placement of placements) {
    const nextPlacement = rows.find(row => row.name === 'DegeneretteBetPlaced'
      && matches(row) && compareLogs(row, placement) > 0);
    const result = rows.find(row => row.name === 'DegeneretteResolved' && matches(row)
      && compareLogs(row, placement) > 0
      && (!nextPlacement || compareLogs(row, nextPlacement) < 0));
    // The immutable settlement bounds its RNG search. Later uses of this
    // buffer are irrelevant, even when the player returns much later.
    const session = result ? await lootboxSession(s, index, {
      fromBlock: placement.blockNumber, toBlock: result.blockNumber, afterLogIndex: placement.logIndex,
    }) : { word: 0n, applied: null, next: null };
    if (rngWord != null && BigInt(rngWord) > 0n && session.word !== BigInt(rngWord)) continue;
    candidates.push({ placement, session, result });
  }
  // Old browser receipts lack a transaction anchor. Recover only an unambiguous
  // match; never substitute another use of the same physical queue slot.
  if (candidates.length !== 1) return null;
  const { placement, session, result } = candidates[0];
  if (!result || !inLootboxSession(result, session, placement)) return null;

  const deg = await import('../app/degenerette.js');
  const packed = BigInt(placement.args.packed);
  const bet = deg.decodeDegeneretteBetWord(packed);
  const spins = deg.degeneretteSpinResults({ ...result.args, player }, packed);
  if (!bet || !spins || spins.length !== bet.spinCount) return null;
  // Require the receipt too: an ETH win can include a direct luckbox, and a
  // missing receipt must not silently retire that part of the pending work.
  const full = await client.receipt(result.transactionHash, undefined, result.blockHash);
  if (!Array.isArray(full?.logs)) return null;
  await prepareWalletReceipt(full, client);
  const receipt = deg.degeneretteSettlementReceipt(full, {
    player, index, betId, packedData: packed, game: client.address('GAME'),
  });
  if (!receipt?.logs?.length) return null;
  let recordStake = 0n;
  if (bet.recordArmed) {
    const placed = await client.receipt(placement.transactionHash, undefined, placement.blockHash);
    await prepareWalletReceipt(placed, client);
    recordStake = deg.parseRecordStakeFromReceipt(placed, player, { coinflip: client.address('COINFLIP') });
  }
  await s.verify();
  return {
    resolved: { player, index: BigInt(index), betId: BigInt(betId), spinCount: BigInt(bet.spinCount),
      totalPayout: deg.degeneretteTotalPayoutFromChain(result.args.totalPayout, packed),
      resultTraits: BigInt(result.args.resultTraits), spins: deg.decodeDegeneretteSpins(result.args.spins),
      spinsData: result.args.spins, transactionHash: result.transactionHash,
      blockNumber: result.blockNumber, logIndex: result.logIndex },
    spins, packedData: packed, receipt, transactionHash: result.transactionHash,
    rngWord: session.word, recordStake, placementHash: placement.transactionHash,
  };
}
